void bubbleSort(int* arr, int size) {
    for (int i = 0; i < size; i++) {
        int swapped = 0;
        for (int j = 0; j < size - 1 - i; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(&arr[j], &arr[j + 1]);
                swapped = 1;
            }
        }
        if (!swapped) break;    // redan sorterad: O(n) i best case
    }
}
